-- Migration 019 (Postgres): inbound email intake tables for M365 shared mailbox

CREATE TABLE IF NOT EXISTS "AP_INBOUND_EMAIL" (
  "InboundEmailId" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "MessageId" TEXT NOT NULL,
  "InternetMessageId" VARCHAR(500) NULL,
  "FromAddress" VARCHAR(320) NULL,
  "Subject" VARCHAR(1000) NULL,
  "ReceivedAt" TIMESTAMP NULL,
  "HasAttachments" BOOLEAN NOT NULL DEFAULT FALSE,
  "Status" VARCHAR(40) NOT NULL DEFAULT 'PENDING',
  "VendorId" INTEGER NULL,
  "VendorMatched" BOOLEAN NOT NULL DEFAULT FALSE,
  "ErrorMessage" TEXT NULL,
  "MailboxFolder" VARCHAR(100) NULL,
  "CreatedAt" TIMESTAMP NOT NULL DEFAULT NOW(),
  "UpdatedAt" TIMESTAMP NULL,
  CONSTRAINT "PK_AP_INBOUND_EMAIL" PRIMARY KEY ("InboundEmailId"),
  CONSTRAINT "UQ_AP_INBOUND_EMAIL_MessageId" UNIQUE ("MessageId"),
  CONSTRAINT "CK_AP_INBOUND_EMAIL_Status" CHECK (
    "Status" IN ('PENDING', 'PROCESSED', 'NO_DOCUMENT', 'FAILED', 'IGNORED', 'VENDOR_UNMATCHED')
  )
);

CREATE INDEX IF NOT EXISTS "IX_AP_INBOUND_EMAIL_Status_ReceivedAt"
  ON "AP_INBOUND_EMAIL" ("Status", "ReceivedAt" DESC);

CREATE INDEX IF NOT EXISTS "IX_AP_INBOUND_EMAIL_FromAddress"
  ON "AP_INBOUND_EMAIL" ("FromAddress");

CREATE TABLE IF NOT EXISTS "AP_INBOUND_EMAIL_ATTACHMENT" (
  "InboundAttachmentId" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "InboundEmailId" BIGINT NOT NULL,
  "AttachmentId" TEXT NOT NULL,
  "FileName" VARCHAR(500) NULL,
  "MimeType" VARCHAR(150) NULL,
  "FileSizeBytes" BIGINT NULL,
  "DocumentId" BIGINT NULL,
  "Status" VARCHAR(40) NOT NULL DEFAULT 'PENDING',
  "ErrorMessage" TEXT NULL,
  "CreatedAt" TIMESTAMP NOT NULL DEFAULT NOW(),
  "UpdatedAt" TIMESTAMP NULL,
  CONSTRAINT "PK_AP_INBOUND_EMAIL_ATTACHMENT" PRIMARY KEY ("InboundAttachmentId"),
  CONSTRAINT "UQ_AP_INBOUND_EMAIL_ATTACHMENT_Msg_Att" UNIQUE ("InboundEmailId", "AttachmentId"),
  CONSTRAINT "CK_AP_INBOUND_EMAIL_ATTACHMENT_Status" CHECK (
    "Status" IN ('PENDING', 'PROCESSED', 'SKIPPED', 'FAILED')
  ),
  CONSTRAINT "FK_AP_INBOUND_EMAIL_ATTACHMENT_Email"
    FOREIGN KEY ("InboundEmailId") REFERENCES "AP_INBOUND_EMAIL" ("InboundEmailId")
    ON DELETE NO ACTION ON UPDATE NO ACTION
);

CREATE INDEX IF NOT EXISTS "IX_AP_INBOUND_EMAIL_ATTACHMENT_DocumentId"
  ON "AP_INBOUND_EMAIL_ATTACHMENT" ("DocumentId");
